function drawIndependentStems(p){const groups=new Map();p.rhythmStems.forEach(t=>{const k=M.rhythmKey(t.rhythm);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(t);});const list=[...groups.values()].sort((a,b)=>Math.min(...a.map(t=>t.pitch))-Math.min(...b.map(t=>t.pitch)));let out='';list.forEach((tones,i)=>{const r=tones[0].rhythm,down=i===0||i>1&&Math.max(...tones.map(t=>t.pitch))>p.bottomPitch+4,ys=tones.map(t=>t.y),sx=tones[0].x+(down?.6:13.6),from=down?Math.min(...ys):Math.max(...ys),extension=36+Math.max(0,Math.log2(r.duration)-5)*4,end=down?Math.max(...ys)+extension:Math.min(...ys)-extension;if(r.duration!==1){out+=line(sx,from,sx,end,'note-ink independent-stem','stroke-width="1.3"');if(r.duration>=8)out+=glyph(String.fromCodePoint(0xE240+2*(Math.log2(r.duration)-3)+(down?1:0)),sx,end,48,'music-text note-ink');}p.stemEnd=down?Math.max(p.stemEnd,end):Math.min(p.stemEnd,end);});return out;}
function hideMenu(){cancelShowMenu();clearTimeout(hideMenuTimer);hideMenuTimer=null;finishLyricEdit();$('contextMenu').hidden=true;menuTarget=null;}
function cancelHideMenu(){clearTimeout(hideMenuTimer);hideMenuTimer=null;}
function scheduleHideMenu(){if($('contextMenu').hidden||hideMenuTimer!==null)return;hideMenuTimer=setTimeout(()=>{hideMenuTimer=null;if(!$('contextMenu').matches(':hover'))hideMenu();},120);}
function isSelectedTarget(t){return t?.type==='note'?(t.toneIndex===undefined?selectedNotes.has(t.id):isToneSelected(t.id,t.toneIndex)):t?.type==='measure'?!!selectedMeasureVoices.get(score.measures[t.mi]?.id)?.has(t.voice):t?.type==='symbol'?selectedSymbols.has(symbolKey(t)):false;}
function targetAt(element){const sym=element.closest('[data-symbol-kind]');if(sym)return {type:'symbol',kind:sym.dataset.symbolKind,mi:+sym.dataset.symbolMi,id:sym.dataset.symbolId||'',graceId:sym.dataset.graceId||''};const note=element.closest('[data-id]');if(note){const f=findNote(note.dataset.id),tone=element.closest('[data-tone-index]');return f?{type:'note',id:f.e.id,mi:f.mi,toneIndex:tone?+tone.dataset.toneIndex:undefined}:null;}const bar=element.closest('.measure-click');return bar?{type:'measure',mi:+bar.dataset.mi,voice:bar.dataset.voice}:null;}
function toneIndexAt(p,point){return headHit(p,point)?.toneIndex??p?.headBoxes?.reduce((best,h)=>!best||Math.abs(h.y-point.y)<Math.abs(best.y-point.y)?h:best,null)?.toneIndex??0;}

function hoverTargetAt(event){if(mode!=='select'||symbolTool||playbackMarkerTool)return null;const t=targetAt(event.target);if(t?.type==='note'){const p=notePositions.get(t.id),point=coordinates(event);if(!p||!point)return null;t.toneIndex=t.toneIndex??toneIndexAt(p,point);const ys=[...p.headYs];if(p.e.duration!==1&&p.e.type==='note')ys.push(p.stemEnd);if(point.x<p.x-26||point.x>p.x+35||point.y<Math.min(...ys)-12||point.y>Math.max(...ys)+12)return null;}return t;}
function cancelShowMenu(){clearTimeout(showMenuTimer);showMenuTimer=null;hoverPending=null;}
function hoverKey(t){return t.type==='symbol'?symbolKey(t):t.type+':'+(t.id??t.mi)+':'+(t.voice||'')+':'+(t.toneIndex??'');}
function queueHoverMenu(t,x,y){if(!t||!isSelectedTarget(t)||symbolTool||gesture?.dragging){cancelShowMenu();scheduleHideMenu();return;}cancelHideMenu();const key=hoverKey(t);if(menuTarget&&hoverKey(menuTarget)===key&&!$('contextMenu').hidden)return;if(hoverPending?.key===key){hoverPending.x=x;hoverPending.y=y;return;}hideMenu();hoverPending={key,t,x,y};showMenuTimer=setTimeout(()=>{const pending=hoverPending;showMenuTimer=null;hoverPending=null;if(pending&&mode==='select'&&isSelectedTarget(pending.t)&&!gesture?.dragging&&!symbolTool)showMenu(pending.t,pending.x,pending.y);},480);}
function showMenu(t,x,y){if(mode!=='select'||symbolTool){hideMenu();return;}if(!isSelectedTarget(t)){scheduleHideMenu();return;}cancelHideMenu();const key=t.type==='symbol'?symbolKey(t):t.type+':'+(t.id||t.mi)+':'+(t.voice||''),old=menuTarget;menuTarget=t;menuTarget._key=key;const menu=$('contextMenu');if(menu.hidden||old?._key!==key){buildMenu();menu.hidden=false;const width=menu.offsetWidth,left=x+12+width<=window.innerWidth-8?x+12:x-width-12;menu.style.left=Math.max(8,Math.min(left,window.innerWidth-width-8))+'px';menu.style.top=Math.max(8,Math.min(y+8,window.innerHeight-menu.offsetHeight-84))+'px';}}
function menuChoice(label,attr,value,active=false){return `<button class="menu-choice${active?' active':''}" ${attr}="${escapeXml(JSON.stringify(value))}">${escapeXml(label)}</button>`;}
const propChoice=(k,v,label)=>menuChoice(label,`data-prop="${k}" data-value`,v);
const settingChoice=(k,v,label)=>menuChoice(label,`data-setting="${k}" data-value`,v);
const actionChoice=(action,label)=>`<button class="menu-choice" data-action="${action}">${escapeXml(label)}</button>`;
function repeatPicker(id,count,action){return '<label class="menu-field">共播放（遍）<input id="'+id+'" type="number" min="1" step="1" value="'+escapeXml(String(count||2))+'"></label>'+actionChoice(action,'设置反复次数');}
function setRepeatCount(inputId,edit=false){try{const count=M.repeatCount($(inputId).value);$('repeatTimes').value=count;if(edit)editSymbols(count);else useSymbol('repeatEnd',count,'𝄇 共 '+count+' 遍');}catch(e){toast(e.message);}}
function category(label,html){return `<div class="menu-category"><button class="menu-category-title" aria-expanded="false">${escapeXml(label)}<span aria-hidden="true">›</span></button><div class="submenu">${html}</div></div>`;}
function buildMenu(){if(!menuTarget||!isSelectedTarget(menuTarget)){hideMenu();return;}const notes=selectedList(),bars=score.measures.filter(m=>selectedMeasures.has(m.id)),f=getSelected(),c=config();let out='';
  if(notes.length)out+=category('升降记号',[[null,'由调号与小节决定'],[1,'♯ 升'],[-1,'♭ 降'],[0,'♮ 还原'],[2,'𝄪 重升'],[-2,'𝄫 重降']].map(([v,l])=>propChoice('accidental',v,l)).join(''));
  if(notes.length)out+=category('时值',[1,2,4,8,16,32,64,128].map(d=>propChoice('duration',d,`${d} 分音符`)).join('')+'<div class="menu-divider"></div>'+[0,1,2,3].map(d=>propChoice('dots',d,['无附点','附点 ·','复附点 ··','三附点 ···'][d])).join(''));
  if(bars.length){out+=category('调号',(c.mode==='minor'?M.MINOR:M.MAJOR).map((n,i)=>settingChoice('key',i-7,n+(c.mode==='minor'?' 小调':' 大调'))).join(''));out+=category('调式',settingChoice('mode','major','大调')+settingChoice('mode','minor','小调'));out+=category('拍号／节奏',meterValues.map(v=>settingChoice('meter',v.split('/').map(Number),v)).join(''));out+=category('速度',`<label class="menu-field">♩ / 分钟<input id="menuBpm" type="number" step="any" value="${c.bpm}"></label>`+actionChoice('setBpm','设置速度…'));out+=category('当前声部谱号',Object.entries(clefNames).map(([v,l])=>settingChoice('clef',v,l)).join(''));}
  if(notes.length||bars.length){out+=category('力度',propChoice('dynamic','','取消力度')+dynamics.map(v=>propChoice('dynamic',v,v)).join(''));out+=category('表情',propChoice('expression','','取消表情')+M.EXPRESSIONS.map(([v,l])=>propChoice('expression',v,`${v} · ${l}`)).join(''));out+=category('奏法',propChoice('articulation','','取消奏法')+articulations.map(([v,l])=>propChoice('articulation',v,l)).join(''));out+=category('装饰音',propChoice('ornament','','取消装饰音')+[['trill','tr · 颤音'],['mordent','波音'],['turn','回音']].map(([v,l])=>propChoice('ornament',v,l)).join(''));out+=category('八度线',[[0,'取消八度线'],[1,'8va · 高八度'],[-1,'8vb · 低八度'],[2,'15ma · 高两八度'],[-2,'15mb · 低两八度']].map(([v,l])=>menuChoice(l,'data-menu-symbol="ottava" data-value',v)).join(''));}
  if(notes.length){out+=category('连线',menuChoice('添加延音线','data-menu-symbol="tie" data-value',true)+propChoice('tie',false,'取消延音线')+menuChoice('添加圆滑线','data-menu-symbol="slur" data-value','add')+actionChoice('removeSlur','取消圆滑线'));out+=category('音高',actionChoice('pitchUp',notation==='jianpu'?'↑ 上移八度':'↑ 上移一个谱位')+actionChoice('pitchDown',notation==='jianpu'?'↓ 下移八度':'↓ 下移一个谱位'));const lyric=notes.find(e=>e.id===selected&&e.type==='note')||notes.find(e=>e.type==='note');if(lyric)out+=category('歌词',`<label class="menu-field">歌词<input id="menuLyric" data-lyric-id="${lyric.id}" value="${escapeXml(lyric.lyric)}" maxlength="80" placeholder="输入歌词，Enter 保存"></label>`+actionChoice('saveLyric','保存歌词'));}
  if(bars.length)out+=category('反复／返回',menuChoice('𝄆 反复起点','data-menu-symbol="repeatStart" data-value',true)+menuChoice('取消反复起点','data-menu-symbol="repeatStart" data-value',false)+repeatPicker('menuRepeatCount',bars[0]?.repeatEnd||$('repeatTimes').value,'setRepeatCount')+menuChoice('取消反复终点','data-menu-symbol="repeatEnd" data-value',0)+['','1','2','3','1,2','2,3'].map(v=>menuChoice(v?`${v}. 结尾`:'取消结尾','data-menu-symbol="ending" data-value',v)).join('')+Object.entries(navNames).map(([v,l])=>menuChoice(l,'data-menu-symbol="navigation" data-value',v)).join('')+menuChoice('取消返回标记','data-menu-symbol="navigation" data-value',''));
  if(notes.length||bars.length)out+=category('渐强／渐弱',menuChoice('＜','data-menu-symbol="hairpin" data-value','crescendo')+menuChoice('＞','data-menu-symbol="hairpin" data-value','diminuendo')+propChoice('expression','cresc.','cresc.')+propChoice('expression','dim.','dim.')+actionChoice('clearHairpins','取消渐强／渐弱线'));
  if(notes.length){out+=category('琶音',menuChoice('𝆃','data-menu-symbol="arpeggio" data-value','plain')+menuChoice('𝆃 ↑','data-menu-symbol="arpeggio" data-value','up')+menuChoice('𝆃 ↓','data-menu-symbol="arpeggio" data-value','down')+propChoice('arpeggio','','取消琶音'));out+=category('滑音',menuChoice('╱','data-menu-symbol="glissando" data-value','straight')+menuChoice('∿','data-menu-symbol="glissando" data-value','wavy')+propChoice('glissando','','取消滑音'));out+=category('符梁',actionChoice('beamAuto','按拍自动连接')+actionChoice('beamJoin','连接所选连续音符')+actionChoice('beamBreak','断开所选符梁'));if(f?.e.chord?.length)out+=category('和弦',actionChoice('removeChordTone','删除所点的和弦音'));if(notes.some(e=>e.graceNotes?.length))out+=category('倚音',actionChoice('removeGraces','删除所选音符的倚音'));}
  if(selectedSymbols.size){const t=[...selectedSymbols.values()].at(-1);let html='';if(t.kind==='hairpin'||t.kind==='measureHairpin')html=['crescendo','diminuendo'].map((v,i)=>menuChoice(i?'＞':'＜','data-symbol-value',v)).join('');else if(t.kind==='glissando')html=['straight','wavy'].map((v,i)=>menuChoice(i?'∿':'╱','data-symbol-value',v)).join('');else if(t.kind==='arpeggio')html=['plain','up','down'].map((v,i)=>menuChoice(['𝆃','𝆃 ↑','𝆃 ↓'][i],'data-symbol-value',v)).join('');else if(t.kind==='ottava'||t.kind==='measureOctave')html=[[0,'取消八度线'],[1,'8va'],[-1,'8vb'],[2,'15ma'],[-2,'15mb']].map(([v,l])=>menuChoice(l,'data-symbol-value',v)).join('');else if(t.kind==='repeatEnd')html=repeatPicker('repeatSymbolCount',score.measures[t.mi].repeatEnd,'updateRepeatCount');else if(t.kind==='ending')html=['1','2','3','1,2','2,3'].map(v=>menuChoice(`${v}. 结尾`,'data-symbol-value',v)).join('');else if(t.kind==='navigation')html=Object.entries(navNames).map(([v,l])=>menuChoice(l,'data-symbol-value',v)).join('');else if(t.kind==='tuplet'){const e=findNote(t.id)?.e;html=`<label class="menu-field">连音数量<input id="menuTupletCount" type="number" min="2" max="32" value="${e?.tuplet?.count||3}"></label><label class="menu-field">总时值（四分拍）<input id="menuTupletTotal" type="number" min="0.125" max="32" step="0.125" value="${e?.tuplet?.total||1}"></label>`+actionChoice('updateTuplet','修改连音组');}out+=category('所选符号',html+actionChoice('removeSymbols','删除所选符号'));}
  out+=category('删除',actionChoice('delete','删除所选对象'));$('contextMenu').innerHTML=out;filterJianpuMenu();
}
function openCategory(cat){const menu=$('contextMenu');menu.querySelectorAll('.menu-category').forEach(e=>{e.classList.toggle('open',e===cat);e.querySelector('.menu-category-title').setAttribute('aria-expanded',String(e===cat));});const sub=cat.querySelector('.submenu'),r=cat.getBoundingClientRect(),mr=menu.getBoundingClientRect();sub.style.left=Math.max(8,Math.min(mr.right-1,window.innerWidth-sub.offsetWidth-8))+'px';sub.style.top=Math.max(8,Math.min(r.top,window.innerHeight-sub.offsetHeight-82))+'px';}
$('contextMenu').addEventListener('pointerover',e=>{cancelHideMenu();const cat=e.target.closest('.menu-category');if(cat&&!cat.classList.contains('open'))openCategory(cat);});$('contextMenu').addEventListener('pointerleave',scheduleHideMenu);
document.addEventListener('pointerover',e=>{if(!$('score').contains(e.target)&&!$('contextMenu').contains(e.target))hideMenu();});window.addEventListener('blur',hideMenu);
function setAnnotation(k,v){if(['dynamic','expression','articulation','ornament'].includes(k))commit(()=>{selectedList().forEach(e=>e[k]=v);score.measures.filter(m=>selectedMeasures.has(m.id)).forEach(m=>m[k]=v);});else setProp(k,v);}
function saveLyric(){const input=$('menuLyric');if(!input)return;const f=findNote(input.dataset.lyricId),value=input.value;if(f)commit(()=>f.e.lyric=value);}
function finishLyricEdit(){if(lyricEditBefore!==null&&lyricEditBefore!==snapshot()){undoStack.push(lyricEditBefore);if(undoStack.length>120)undoStack.shift();redoStack=[];recordRecentContent(JSON.parse(lyricEditBefore));}lyricEditBefore=null;}
$('contextMenu').addEventListener('focusin',e=>{if(e.target.id==='menuLyric')lyricEditBefore=snapshot();});
$('contextMenu').addEventListener('input',e=>{if(e.target.id!=='menuLyric')return;const f=findNote(e.target.dataset.lyricId);if(f){f.e.lyric=e.target.value;renderScore();save();}});
$('contextMenu').addEventListener('focusout',e=>{if(e.target.id==='menuLyric'){finishLyricEdit();syncTools();}});
$('contextMenu').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('menu-category-title')){openCategory(b.parentElement);return;}if(b.dataset.setting){requestSetting(b.dataset.setting,JSON.parse(b.dataset.value));return;}if(b.dataset.prop){setAnnotation(b.dataset.prop,JSON.parse(b.dataset.value));return;}if(b.dataset.menuSymbol){useSymbol(b.dataset.menuSymbol,JSON.parse(b.dataset.value),b.textContent);return;}if(b.hasAttribute('data-symbol-value')){editSymbols(JSON.parse(b.dataset.symbolValue));return;}const action=b.dataset.action;if(action==='setRepeatCount')setRepeatCount('menuRepeatCount');if(action==='updateRepeatCount')setRepeatCount('repeatSymbolCount',true);if(action==='beamAuto')setBeaming('auto');if(action==='beamJoin')setBeaming('join');if(action==='beamBreak')setBeaming('break');if(action==='removeChordTone')removeChordTone();if(action==='removeGraces')commit(()=>selectedList().forEach(e=>e.graceNotes=[]));if(action==='clearHairpins')commit(()=>{selectedList().forEach(e=>{e.hairpin='';e.hairpinTo='';});score.measures.filter(m=>selectedMeasures.has(m.id)).forEach(m=>selectedMeasureVoices.get(m.id)?.forEach(v=>delete m.hairpins?.[v]));});if(action==='delete')deleteSelected();if(action==='pitchUp')movePitch(notation==='jianpu'?7:1);if(action==='pitchDown')movePitch(notation==='jianpu'?-7:-1);if(action==='setBpm')requestSetting('bpm',Number($('menuBpm').value));if(action==='saveLyric')saveLyric();if(action==='removeSlur')commit(()=>{const ids=new Set(selectedList().map(e=>e.slur).filter(Boolean));score.measures.flatMap(m=>m.events).filter(e=>ids.has(e.slur)).forEach(e=>e.slur='');});if(action==='removeSymbols')commit(()=>{selectedSymbols.forEach(removeSymbol);selectedSymbols.clear();hideMenu();});if(action==='updateTuplet')updateTupletSymbols();});
$('contextMenu').addEventListener('keydown',e=>{if(e.key!=='Enter')return;if(e.target.id==='menuLyric'){e.preventDefault();saveLyric();}if(e.target.id==='menuRepeatCount'){e.preventDefault();setRepeatCount('menuRepeatCount');}if(e.target.id==='repeatSymbolCount'){e.preventDefault();setRepeatCount('repeatSymbolCount',true);}});
$('contextMenu').addEventListener('change',e=>{if(e.target.id==='menuLyric')saveLyric();});
function requestSetting(k,value,origin=null){if(k==='bpm'&&(!Number.isFinite(value)||value<=0)){toast('速度须为大于 0 的数字。');syncSettings();return;}hideMenu();closeScoreSetting();const chosen=score.measures.map((m,i)=>selectedMeasures.has(m.id)?i:-1).filter(i=>i>=0),target=origin?.mi??currentMeasure,indices=chosen.length&&(!origin||chosen.includes(target))?chosen:[target],start=Math.min(...indices);pendingScope={k,value,indices,start,voice:origin?.voice||activeVoice};$('scopeDescription').textContent=`${{key:'调号',mode:'调式',meter:'拍号',bpm:'速度',clef:'谱号'}[k]}修改 · 第 ${start+1} 小节${indices.length>1?'；“当前小节”会修改全部选中的小节':''}`;$('scopeDialog').showModal();}
function applyScope(following){const p=pendingScope;pendingScope=null;$('scopeDialog').close();if(!p)return;commit(()=>{const indices=following?score.measures.map((m,i)=>i).filter(i=>i>=p.start):p.indices;indices.forEach(mi=>{const m=score.measures[mi];if(p.k==='clef'){m.clefs??={};m.clefs[p.voice]=p.value;}else m[p.k]=Array.isArray(p.value)?[...p.value]:p.value;});});}
$('scopeCurrent').onclick=()=>applyScope(false);$('scopeFollowing').onclick=()=>applyScope(true);$('cancelScope').onclick=()=>{pendingScope=null;$('scopeDialog').close();syncSettings();};$('scopeDialog').addEventListener('cancel',()=>{pendingScope=null;syncSettings();});

function finishMeasure(mi=currentMeasure,vid=activeVoice){const m=score.measures[mi];if(!m)return;const es=M.events(score,m,vid);if(M.close(es.reduce((a,e)=>a+M.ticks(e),0),M.capacity(score,mi)))es.filter(e=>!e.manualPosition).forEach(e=>e.positionRatio=null);}
function finishCompleteMeasures(){score.measures.forEach((m,mi)=>score.voices.forEach(v=>finishMeasure(mi,v.id)));}
function focusMeasure(mi,vid){if(currentMeasure!==mi||activeVoice!==vid)finishMeasure();currentMeasure=mi;activeVoice=vid;}
function inputDefaults(){return {duration:defaults.duration,dots:defaults.dots,exactTicks:defaults.exactTicks??null,accidental:null,dynamic:'',expression:'',articulation:'',ornament:'',ottava:0,tie:false,triplet:false};}
function addChordTone(id,pitch){const f=findNote(id);if(!f)return;staffLastInputId=id;staffLastInputToneIndex=0;focusMeasure(f.mi,f.e.voice);clearSelection();commit(()=>{if(f.e.type==='rest'){f.e.type='note';f.e.pitch=pitch;f.e.chord=[];f.e.placeholder=false;}else{const existing=M.tones(f.e).findIndex(t=>t.pitch===pitch);if(existing>=0){staffLastInputToneIndex=existing;return;}f.e.chord??=[];if(f.e.chord.length>=31)throw Error('单个和弦最多 32 个音。');f.e.chord.push({pitch,accidental:null});M.syncChordRhythm(f.e);staffLastInputToneIndex=f.e.chord.length;}});}
function addGraceAt(g,point,t){const anchor=t?.type==='note'?notePositions.get(t.id):g.positions.filter(p=>p.e.type==='note').sort((a,b)=>Math.abs(a.x-point.x)-Math.abs(b.x-point.x))[0];if(!anchor||anchor.e.type!=='note'){toast('请先输入主音，再选择倚音并点击主音左侧的谱位。');return;}const pitch=Math.max(0,Math.min(66,g.bottomPitch+Math.round((g.base-point.y)/6)));commit(()=>{anchor.e.graceNotes??=[];if(anchor.e.graceNotes.length>=16)throw Error('每个主音最多 16 个倚音。');anchor.e.graceNotes.push({id:M.id(),pitch,accidental:null,duration:[8,16,32].includes(defaults.duration)?defaults.duration:8,slash:$('graceInput').value==='slashed'});});}
function headHit(p,point){return p?.headBoxes?.find(h=>Math.abs(h.x-point.x)<=8.5&&Math.abs(h.y-point.y)<=(h.rest?13:5.5));}
function scoreClick(e){if(consumeGestureClick){consumeGestureClick=false;return;}if(Date.now()<suppressClickUntil)return;const setting=e.target.closest?.('[data-score-setting]');if(setting){openScoreSetting(setting,e);return;}closeScoreSetting();if(notation==='jianpu'){jianpuClick(e);return;}
  if(Date.now()<suppressClickUntil)return;hideMenu();menuArmPoint={x:e.clientX,y:e.clientY};const t=targetAt(e.target),add=mode==='select'&&(e.ctrlKey||e.metaKey),point=coordinates(e);
  if(playbackMarkerTool&&t){placePlaybackMarker(t);return;}if(mode==='edit'&&t?.type==='symbol'&&['grace','articulation','measureArticulation'].includes(t.kind)){commit(()=>removeSymbol(t));return;}if(symbolTool&&t){placeSymbol(t);return;}
  const label=e.target.closest('.voice-label');if(label){finishMeasure();activeVoice=label.dataset.voice;clearSelection();stop();render();return;}
  if(!point)return;
  if(mode==='select'){if(t?.type==='note'&&findNote(t.id)?.e.chord?.length){const now=Date.now();if(lastChordClick?.id===t.id&&now-lastChordClick.time<340&&Math.hypot(e.clientX-lastChordClick.x,e.clientY-lastChordClick.y)<=6){lastChordClick=null;select(t.id,add,null,true);queueHoverMenu(t,e.clientX,e.clientY);return;}lastChordClick={id:t.id,time:now,x:e.clientX,y:e.clientY};}else lastChordClick=null;if(t?.type==='symbol')selectSymbol(t,add);else if(t?.type==='note')select(t.id,add,t.toneIndex??toneIndexAt(notePositions.get(t.id),point));else if(t?.type==='measure')selectMeasure(t.mi,t.voice,add);menuArmPoint=null;if(t){if(t.type==='note')t.toneIndex=t.toneIndex??toneIndexAt(notePositions.get(t.id),point);queueHoverMenu(t,e.clientX,e.clientY);}$('score').focus({preventScroll:true});return;}
  if(t?.type==='symbol')return;
  const g=t?.type==='note'?geometry.find(g=>g.mi===t.mi&&g.voice===findNote(t.id)?.e.voice):t?.type==='measure'?geometry.find(g=>g.mi===t.mi&&g.voice===t.voice):null;if(!g)return;focusMeasure(g.mi,g.voice);
  if($('graceInput').value){addGraceAt(g,point,t);return;}
  const pitch=Math.max(0,Math.min(66,g.bottomPitch+Math.round((g.base-point.y)/6)));
  if(t.type==='note'){const p=notePositions.get(t.id);if(headHit(p,point)){cycleNote(t.id);$('score').focus({preventScroll:true});return;}if(Math.abs(p.x+7-point.x)<=6&&point.y>=g.top-72&&point.y<=g.base+72){addChordTone(t.id,pitch);$('score').focus({preventScroll:true});return;}} 
  const at=g.positions.find(p=>!p.e.placeholder&&(headHit(p,point)||Math.abs(p.x+7-point.x)<=6));if(at){if(headHit(at,point))cycleNote(at.e.id);else addChordTone(at.e.id,pitch);return;}
  const following=g.positions.find(n=>point.x<n.x&&!n.e.placeholder),n=M.event(pitch,{...inputDefaults(),voice:activeVoice,type:'note',entryAnchor:true,positionRatio:positionRatio(g,point.x)});clearSelection();commit(()=>{clearPlaceholders(currentMeasure,activeVoice);const arr=score.measures[currentMeasure].events,idx=following?arr.findIndex(e=>e.id===following.e.id):arr.length;arr.splice(idx,0,n);staffLastInputId=n.id;staffLastInputToneIndex=0;});$('score').focus({preventScroll:true});
}
