function appendEmptyMeasure(){if(score.measures.length>=300)throw new Error('最多 300 小节。');const c=config(score.measures.length-1),clefs={};score.voices.forEach(v=>clefs[v.id]=config(score.measures.length-1,v.id).clef);score.measures.push(M.measure({key:c.key,mode:c.mode,meter:[...c.meter],bpm:c.bpm,clefs}));}
