function measureHasContent(m,mi){return m.events.some(e=>!e.placeholder)||['dynamic','expression','articulation','ornament','repeatStart','repeatEnd','ending','navigation'].some(k=>m[k])||Object.keys(m.octaves||{}).length>0||Object.keys(m.hairpins||{}).length>0||score.voices.some(v=>JSON.stringify(config(mi,v.id))!==JSON.stringify(config(mi-1,v.id)));}
