function canUseMeasureShortcut(event){return !event.ctrlKey&&!event.metaKey&&!event.isComposing&&!event.target.matches?.('input,select,textarea,[contenteditable="true"]')&&!document.querySelector('dialog[open]');}
function cancelAltMeasure(){clearTimeout(altMeasureTimer);altMeasureTimer=null;altMeasureState=null;measureBatchBefore=null;}
function stepAltMeasure(){const state=altMeasureState;if(!state)return false;if(document.querySelector('dialog[open]')){cancelAltMeasure();return false;}const before=score.measures.length;if(state.direction>0){if(before>=300)return false;addMeasure();}else{if(before<=1)return false;requestMeasureCount(before-1,{confirm:false});}return score.measures.length!==before;}
